<template><view class="card sage"><view class="row between"><view><text class="eyebrow">MY LITTLE GARDEN</text><text class="title">今天的努力，正在开花。</text></view><CartoonArt class="flower-art" kind="sun" label="笑脸太阳花"/></view><view class="row between"><text class="muted">今日专注 {{store.study.today_minutes}} / {{store.settings.daily_goal}} 分钟</text><text class="pill">{{percent}}%</text></view><view class="progress-track"><view class="progress-fill" :style="{width:percent+'%'}"></view></view><view class="row between space"><view><text class="garden-count">连续 {{store.study.streak}} 天</text><text class="muted">累计打卡 {{store.study.checkin_count}} 天</text></view><text class="pill">{{store.study.checked_in?(store.study.early_checked_in?'早起打卡 ✓':'日常打卡 ✓'):'今天还未打卡'}}</text></view></view></template>
<script setup>import CartoonArt from './CartoonArt.vue';import {computed} from 'vue';import {store} from '../services/store';const percent=computed(()=>Math.min(100,Math.round(store.study.today_minutes/store.settings.daily_goal*100)));</script>
<style scoped>.flower{font-size:78rpx;line-height:1;color:#ab9067;transform:rotate(12deg)}.garden-count{font-size:29rpx;display:block;color:#8d734f;margin-bottom:8rpx}.flower-art{width:115rpx;height:115rpx}</style>
